using System;using System.IO;using System.Collections;using UnityEngine;
// Test-only component. One actual gold side; never shipped with the importer.
public sealed class GoldSideMaterialProbe:MonoBehaviour{
 public Renderer face;public Camera proofCamera;public Material[] materials;public string[] modes;
 [Serializable]public class Record{public bool pass;public string unity,api,gpu,colourSpace,error;public int triangles;public string[] modes;public Vector3[] cameraPositions;}
 public void CaptureAll(string output){Directory.CreateDirectory(output);var r=new Record{unity=Application.unityVersion,api=SystemInfo.graphicsDeviceType.ToString(),gpu=SystemInfo.graphicsDeviceName,colourSpace=QualitySettings.activeColorSpace.ToString(),triangles=face.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3,modes=modes,cameraPositions=new Vector3[2]};
 try{for(int view=0;view<2;view++){var target=new Vector3(.5125f,.245f,0);proofCamera.transform.position=target+(view==0?new Vector3(.98f,.34f,.38f):new Vector3(1.65f,1.55f,1.1f));proofCamera.transform.LookAt(target);r.cameraPositions[view]=proofCamera.transform.position;for(int m=0;m<materials.Length;m++){if(!materials[m].shader.isSupported)throw new Exception("unsupported shader "+modes[m]);face.sharedMaterial=materials[m];bool linear=modes[m].Contains("packed")||modes[m]=="weights";var rt=new RenderTexture(900,700,24,RenderTextureFormat.ARGB32,linear?RenderTextureReadWrite.Linear:RenderTextureReadWrite.Default);proofCamera.targetTexture=rt;proofCamera.aspect=900f/700;for(int warm=0;warm<3;warm++)proofCamera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(900,700,TextureFormat.RGB24,false,linear);t.ReadPixels(new Rect(0,0,900,700),0,0);t.Apply();File.WriteAllBytes(Path.Combine(output,(view==0?"near":"overhead")+"-"+modes[m]+".png"),t.EncodeToPNG());RenderTexture.active=previous;proofCamera.targetTexture=null;rt.Release();if(Application.isPlaying){Destroy(t);Destroy(rt);}else{DestroyImmediate(t);DestroyImmediate(rt);}}}r.pass=true;}catch(Exception e){r.error=e.ToString();throw;}finally{File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(r,true));}}
 IEnumerator Start(){for(int i=0;i<8;i++)yield return null;string output=null;var a=Environment.GetCommandLineArgs();int n=Array.IndexOf(a,"-side-output");if(n>=0)output=a[n+1];if(string.IsNullOrEmpty(output)){Application.Quit(1);yield break;}int code=0;try{CaptureAll(output);}catch(Exception e){Debug.LogException(e);code=1;}Application.Quit(code);}
}
